import { Injectable } from '@nestjs/common';
import { InjectDataSource, InjectRepository } from '@nestjs/typeorm';
import { type DataSource, In, IsNull, LessThanOrEqual, MoreThan, type Repository } from 'typeorm';
import { type DebitMovement, creditBalance, debitBalance } from '../balance-ops';
import { type PaymentMeta, type Transaction, UserKey } from '../entities';
import { TransactionKind, UserKeyStatus } from '../enums';

export interface NewUserKey {
  /** Xray client UUID, generated by the caller. */
  id: string;
  userId: string;
  tariffId: string;
  expiresAt: Date;
  trafficLimit: number | null;
}

/** Payment for a key; omitted for free tariffs. */
export type KeyPayment = Omit<DebitMovement, 'userId' | 'kind' | 'meta'> & {
  price?: PaymentMeta['price'];
};

export interface PaidKey {
  key: UserKey;
  /** `null` for a free tariff. */
  payment: Transaction | null;
}

@Injectable()
export class UserKeysRepository {
  constructor(
    @InjectRepository(UserKey) private readonly repo: Repository<UserKey>,
    @InjectDataSource() private readonly dataSource: DataSource,
  ) {}

  /** An active, not expired, not deleted key. */
  findActive(id: string): Promise<UserKey | null> {
    return this.repo.findOneBy({
      id,
      status: UserKeyStatus.Active,
      expiresAt: MoreThan(new Date()),
    });
  }

  /** A key of this user (not deleted), in any status. */
  findOwned(id: string, userId: string): Promise<UserKey | null> {
    return this.repo.findOneBy({ id, userId });
  }

  /** Keys the user sees in the list (not deleted), newest first. */
  findByUser(userId: string, limit?: number): Promise<UserKey[]> {
    return this.repo.find({ where: { userId }, order: { createdAt: 'DESC' }, take: limit });
  }

  /**
   * Charges the balance and stores the key in one DB transaction:
   * either both happen or neither. The key is created on servers afterwards.
   */
  createPaid(input: NewUserKey, payment: KeyPayment | null): Promise<PaidKey> {
    return this.dataSource.transaction(async (manager) => {
      let tx: Transaction | null = null;
      if (payment) {
        const { price, ...debit } = payment;
        const meta: PaymentMeta = { tariffId: input.tariffId, userKeyId: input.id, price };
        tx = await debitBalance(manager, {
          ...debit,
          userId: input.userId,
          kind: TransactionKind.Payment,
          meta,
        });
      }
      const key = await manager.save(manager.create(UserKey, input));
      return { key, payment: tx };
    });
  }

  /**
   * Compensation when the key could not be created on any server:
   * removes the key and returns the payment to the balance. Safe to call twice —
   * the refund is made only by the call that actually removed the key.
   */
  cancelPaid(keyId: string, payment: Transaction | null, reason: string): Promise<boolean> {
    return this.dataSource.transaction(async (manager) => {
      const removed = await manager.softDelete(UserKey, { id: keyId, deletedAt: IsNull() });
      if (removed.affected !== 1) return false;
      if (payment) {
        await creditBalance(manager, {
          userId: payment.userId,
          currency: payment.currency,
          amount: payment.amount,
          kind: TransactionKind.Refund,
          meta: { transactionId: payment.id, reason },
        });
      }
      return true;
    });
  }

  /** Active keys whose time is up, oldest first. */
  findExpired(now: Date, limit: number): Promise<UserKey[]> {
    return this.repo.find({
      where: { status: UserKeyStatus.Active, expiresAt: LessThanOrEqual(now) },
      order: { expiresAt: 'ASC' },
      take: limit,
    });
  }

  /**
   * Marks keys expired; returns ids that actually changed.
   * Re-checks the time, so a key extended after `findExpired` stays active.
   */
  async markExpired(ids: string[]): Promise<string[]> {
    if (ids.length === 0) return [];
    const result = await this.repo
      .createQueryBuilder()
      .update()
      .set({ status: UserKeyStatus.Expired })
      .where({ id: In(ids), status: UserKeyStatus.Active, expiresAt: LessThanOrEqual(new Date()) })
      .returning(['id'])
      .execute();
    return (result.raw as { id: string }[]).map((r) => r.id);
  }

  /** Ids of keys that must exist on servers: active, unexpired, not deleted. */
  async findLiveIds(): Promise<string[]> {
    const rows = await this.repo.find({
      select: { id: true },
      where: { status: UserKeyStatus.Active, expiresAt: MoreThan(new Date()) },
    });
    return rows.map((r) => r.id);
  }

  /**
   * Of the given ids, those known to be dead (expired or deleted) — safe to remove from servers.
   * Ids unknown to the database are not returned: they are not ours to delete.
   */
  async findDeadIds(ids: string[]): Promise<string[]> {
    if (ids.length === 0) return [];
    const rows = await this.repo
      .createQueryBuilder('k')
      .withDeleted()
      .select('k.id', 'id')
      .where({ id: In(ids) })
      .andWhere('(k.deleted_at IS NOT NULL OR k.status <> :active OR k.expires_at <= now())', {
        active: UserKeyStatus.Active,
      })
      .getRawMany<{ id: string }>();
    return rows.map((r) => r.id);
  }
}
